import csv
import io
import math


def sum_amounts(csv_text):
    """Sum valid values from the amount column and skip malformed rows."""
    total = 0.0

    try:
        rows = csv.DictReader(io.StringIO(csv_text, newline=""))
        for row in rows:
            raw_amount = row.get("amount")
            if raw_amount is None:
                continue

            try:
                amount = float(raw_amount)
            except (TypeError, ValueError):
                continue

            if math.isfinite(amount):
                total += amount
    except (csv.Error, TypeError):
        return total

    return total

